 open(detailMarkup);
 const stepForm=$('#custom-product');let confirmedStep=2;
 function setPersonalStep(step){confirmedStep=step;const noEngraving=stepForm.elements.engravingMode?.value==='none';stepForm.querySelectorAll('[data-personal-step]').forEach(el=>{el.hidden=Number(el.dataset.personalStep)>step+1||(noEngraving&&el.classList.contains('engraving-uploads'));});}
 setPersonalStep(2);
 stepForm.elements.variant?.addEventListener('change',()=>updateEngravingMode(stepForm));
