  if(chosen&&(chosen.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(chosen.type))){input.value='';info.textContent='Envie JPG, PNG ou WebP com até 10 MB.';cta.textContent='Selecionar imagem';if(remove?.classList.contains('engraving-remove'))remove.hidden=true;return;}
