function zoom(){const source=$('#drawer .detailGallery .detailImg');if(!source)return;const d=document.createElement('dialog');d.className='photo-zoom enhanced-zoom';d.innerHTML='<button type="button" class="zoom-close" aria-label="Fechar imagem">✕</button><div class="zoom-stage"><img draggable="false" src="'+esc(source.getAttribute('src'))+'" alt="'+esc(source.alt)+'"></div><div class="zoom-controls"><button type="button" data-zoom="-1" aria-label="Diminuir zoom">−</button><input aria-label="Nível de zoom" type="range" min="1" max="4" step=".1" value="1"><button type="button" data-zoom="1" aria-label="Aumentar zoom">+</button><button type="button" data-zoom="reset">Redefinir</button></div>';document.body.append(d);const stage=d.querySelector('.zoom-stage'),photo=stage.querySelector('img'),range=d.querySelector('input');let scale=1,x=0,y=0,drag=null,pinch=0;const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));function render(){const maxX=stage.clientWidth*(scale-1)/2,maxY=stage.clientHeight*(scale-1)/2;x=clamp(x,-maxX,maxX);y=clamp(y,-maxY,maxY);photo.style.transform='translate('+x+'px,'+y+'px) scale('+scale+')';range.value=scale;}function setZoom(n){scale=clamp(n,1,4);if(scale===1){x=0;y=0;}render();}d.querySelector('.zoom-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close();});d.addEventListener('close',()=>d.remove());range.oninput=()=>setZoom(Number(range.value));d.querySelectorAll('[data-zoom]').forEach(btn=>btn.onclick=()=>setZoom(btn.dataset.zoom==='reset'?1:scale+Number(btn.dataset.zoom)*.5));stage.addEventListener('wheel',e=>{e.preventDefault();setZoom(scale+(e.deltaY<0?.2:-.2));},{passive:false});stage.addEventListener('dblclick',()=>setZoom(scale>1?1:2));const pointers=new Map();stage.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});stage.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY};if(pointers.size===2)pinch=0;});stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const prev=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const pts=[...pointers.values()],dist=Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y);if(pinch)setZoom(scale*dist/pinch);pinch=dist;}else if(scale>1){x+=e.clientX-prev.x;y+=e.clientY-prev.y;render();}});const end=e=>{pointers.delete(e.pointerId);pinch=0;};stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);d.showModal();render();}
function renderProducts(){const grid=$('#grid'),fragment=document.createDocumentFragment();products.filter(p=>p.enabled).forEach((p,i)=>{const article=document.createElement('article');article.className='card piece';article.dataset.productId=p.productId;article.dataset.category=p.category||'Sem categoria';article.innerHTML='<div class="photo">'+(/inox/i.test(p.name)?'<span class="catalog-personalized-label">Seleção São Bento</span>':'')+'<button type="button" class="photoLink" data-commerce-detail="'+esc(p.productId)+'" aria-label="Ver detalhes de '+esc(p.name)+'"><img src="'+esc(p.image)+'" alt="'+esc(p.name)+'" loading="lazy" decoding="async" width="600" height="600"></button><button type="button" class="heart" data-commerce-fav="'+esc(p.productId)+'" aria-label="Favoritar '+esc(p.name)+'" aria-pressed="'+String(!!fav[p.productId])+'">'+(fav[p.productId]?'♥':'♡')+'</button></div><h3><button type="button" class="productName" data-commerce-detail="'+esc(p.productId)+'">'+esc(p.name)+'</button></h3><div class="spec">'+esc(p.description)+'</div><div class="price">'+cash(p.priceCents)+'</div><button type="button" class="primary" data-commerce-detail="'+esc(p.productId)+'">Personalizar e ver produto →</button><button type="button" class="catalog-buy-now" data-commerce-buy="'+esc(p.productId)+'" '+(!p.enabled?'disabled':'')+'>Comprar agora →</button>';fragment.append(article);});grid.replaceChildren(fragment);grid.dataset.catalogReady='true';grid.setAttribute('aria-busy','false');filter();}
function renderCategories(){const nav=$('#categories');if(!nav)return;const current=nav.querySelector('.active')?.dataset.category||'Todos',names=['Todos',...(categories.length?categories:[...new Set(products.map(p=>p.category).filter(Boolean))])];nav.replaceChildren();for(const name of names){const b=document.createElement('button');b.type='button';b.className='category'+(name===current?' active':'');b.dataset.category=name;b.setAttribute('aria-pressed',String(name===current));b.innerHTML='<span class="circle" aria-hidden="true">'+(name==='Todos'?'▦':'◉')+'</span>'+esc(name);nav.append(b);}}
function filter(){const normalizeText=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalizeText($('#search').value),cat=$('#categories .active')?.dataset.category||'Todos',sort=$('#sort').value;const list=[...$('#grid').children];let n=0;for(const el of list){const p=products.find(p=>p.productId===el.dataset.productId),c=p.category||'Sem categoria';el.hidden=!normalizeText(p.name+' '+p.description).includes(q)||(cat!=='Todos'&&c!==cat);if(!el.hidden)n++;}list.sort((a,b)=>{const pa=products.find(p=>p.productId===a.dataset.productId),pb=products.find(p=>p.productId===b.dataset.productId);return sort==='low'?pa.priceCents-pb.priceCents:sort==='high'?pb.priceCents-pa.priceCents:((pa.productId==='produto_02'?-1:pb.productId==='produto_02'?1:0)||(products.indexOf(pa)-products.indexOf(pb)));}).forEach(el=>$('#grid').append(el));$('#results').textContent=n+(n===1?' produto':' produtos');$('#catalog-empty').hidden=!!n;}
let fav={};try{fav=JSON.parse(localStorage.getItem('sb.product-favorites')||'{}');}catch{}
function favorites(){open('<h2>Seus favoritos</h2>'+products.filter(p=>fav[p.productId]).map(p=>'<article class="order-cart-line"><img src="'+esc(p.image)+'" alt="'+esc(p.name)+'"><div><b>'+esc(p.name)+'</b><p>'+cash(p.priceCents)+'</p><button class="primary" data-commerce-detail="'+esc(p.productId)+'">Personalizar / adicionar</button><button type="button" class="textbtn" data-commerce-unfav="'+esc(p.productId)+'">Remover dos favoritos</button></div></article>').join('')+(!products.some(p=>fav[p.productId])?'<p>Toque no coração para guardar um produto.</p>':''));}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const buyId=b.dataset.commerceBuy;if(buyId){e.stopImmediatePropagation();const product=products.find(p=>p.productId===buyId);if(product?.enabled)detail(product,{buyNow:true});return;}const pid=b.dataset.commerceDetail;if(pid){e.stopImmediatePropagation();detail(products.find(p=>p.productId===pid));return;}if(b.dataset.commerceUnfav){e.stopImmediatePropagation();delete fav[b.dataset.commerceUnfav];try{localStorage.setItem('sb.product-favorites',JSON.stringify(fav));}catch{}favorites();return;}if(b.dataset.commerceFav){e.stopImmediatePropagation();const k=b.dataset.commerceFav;fav[k]=!fav[k];b.textContent=fav[k]?'♥':'♡';b.setAttribute('aria-pressed',String(!!fav[k]));try{localStorage.setItem('sb.product-favorites',JSON.stringify(fav));}catch{}return;}if(b.dataset.featurePhoto){e.stopImmediatePropagation();const photo=$('#drawer .detailImg');if(photo)photo.src=b.dataset.featurePhoto;document.querySelectorAll('#drawer [data-feature-photo]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));const counter=$('#detail-photo-count'),total=document.querySelectorAll('#drawer [data-feature-photo]').length;if(counter&&b.dataset.featurePhotoIndex!==undefined)counter.textContent=(Number(b.dataset.featurePhotoIndex)+1)+' / '+total;return;}if(b.classList.contains('zoom-trigger')){zoom();return;}if(b.dataset.removeEngraving){const f=$('#custom-product'),input=f?.elements[b.dataset.removeEngraving];if(input){input.value='';input.dispatchEvent(new Event('change'));rememberDraft();}return;}if(b.dataset.detailQty!==undefined){e.preventDefault();const f=$('#custom-product'),input=f?.elements.quantity;if(input){const next=Math.max(1,Math.min(100,(Number(input.value)||1)+Number(b.dataset.detailQty)));input.value=String(next);input.dispatchEvent(new Event('input',{bubbles:true}));}return;}if(b.dataset.qtyStep!==undefined){e.stopImmediatePropagation();const item=cart[Number(b.dataset.qtyIndex)],next=item?.quantity+Number(b.dataset.qtyStep);if(item&&Number.isInteger(next)&&next>=1&&next<=100){item.quantity=next;save();showCart();}return;}if(b.dataset.customDuplicate!==undefined){const source=cart[Number(b.dataset.customDuplicate)];if(source){if(cart.length>=20){alert('Limite de 20 itens por pedido.');return;}cart.push({...source,lineId:crypto.randomUUID()});save();showCart();}return;}if(b.dataset.customRemove!==undefined){const i=cart[Number(b.dataset.customRemove)];if((i?.front||i?.back||i?.engravingNotes)&&!confirm('Remover este produto personalizado do pedido?'))return;cart.splice(Number(b.dataset.customRemove),1);save();showCart();return;}if(b.dataset.featureAction){e.stopImmediatePropagation();({kits,groups,orders:myOrders,cart:showCart})[b.dataset.featureAction]?.();return;}if(b.dataset.ui==='showCart()'){e.stopImmediatePropagation();showCart();return;}if(b.dataset.ui==='showFav()'){e.stopImmediatePropagation();favorites();return;}if(b.dataset.category||b.dataset.ui?.startsWith('setCategory('))setTimeout(filter,0);},true);
document.addEventListener('change',e=>{if(e.target.dataset.customVariant!==undefined){const i=cart[Number(e.target.dataset.customVariant)];if(i){i.variantId=e.target.value;save();showCart();}return;}if(e.target.dataset.customQuantity!==undefined){const i=cart[Number(e.target.dataset.customQuantity)],q=Number(e.target.value);if(Number.isInteger(q)&&q>0&&q<=100){i.quantity=q;save();showCart();}else e.target.value=i.quantity;}if(e.target.id==='sort')setTimeout(filter,0);});$('#search')?.addEventListener('input',()=>setTimeout(filter,0));
new MutationObserver(count).observe($('#cart-count'),{childList:true,subtree:true,characterData:true});
async function init(){try{const d=await api('/api/commerce/catalog');products=d.products;categories=Array.isArray(d.categories)?d.categories:[];ordersConfigured=d.ordersConfigured;if(legacy.length){cart=legacy.filter(i=>products.some(p=>p.productId===i.productId)&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=10).map(i=>({lineId:crypto.randomUUID(),productId:i.productId,quantity:i.quantity,variantId:(products.find(p=>p.productId===i.productId).variants.find(v=>v.id==='sem_gravacao'&&v.enabled!==false)||enabledVariants(products.find(p=>p.productId===i.productId))[0]||products.find(p=>p.productId===i.productId).variants[0]).id,engraving:'',art:null}));legacy=[];save();}window.SBFeatures.ready=true;renderCategories();renderProducts();}catch(err){catalogError=err.message;const grid=$('#grid');if(grid){grid.innerHTML='<p class="catalog-error" role="status">Não foi possível carregar os produtos e preços. Atualize a página para tentar novamente.</p>';grid.dataset.catalogReady='error';grid.setAttribute('aria-busy','false');}const n=$('#features-message');if(n)n.textContent='Recursos temporariamente indisponíveis. Atualize para tentar novamente.';}count();}
window.SBFeatures={kits,groups,myOrders,showCart,detail,file,api,post,filter,closeDrawer:close,ready:false,detailByIndex:i=>detail(products[i])};init();
